// src/components/ProgressBar/ProgressBar.jsx
import React from 'react';
import PropTypes from 'prop-types';
import classnames from 'classnames';
import { settings } from 'carbon-components';
import './ProgressBar.scss';

const { prefix } = settings;

/**
 * A simple percent-complete Progress Bar with optional info lines above and below.
 */
const ProgressBar = ({ value, max, infoAbove, infoBelow, className }) => {
  const percent = Math.round((value / max) * 100);
  return (
    <div className={classnames(`${prefix}--progress-bar`, className)}>
      {infoAbove && <div className={`${prefix}--progress-bar__info-above`}>{infoAbove}</div>}
      <div className={`${prefix}--progress-bar__track`}>        
        <div
          className={`${prefix}--progress-bar__fill`}
          style={{ width: `${percent}%` }}
          aria-valuenow={value}
          aria-valuemax={max}
          aria-valuemin={0}
          role="progressbar"
        />
        <div className={`${prefix}--progress-bar__label`}>{percent}%</div>
      </div>
      {infoBelow && <div className={`${prefix}--progress-bar__info-below`}>{infoBelow}</div>}
    </div>
  );
};

ProgressBar.propTypes = {
  /** number of completed units */
  value: PropTypes.number.isRequired,
  /** total units */
  max: PropTypes.number,
  /** optional content above the bar */
  infoAbove: PropTypes.node,
  /** optional content below the bar */
  infoBelow: PropTypes.node,
  /** extra className */
  className: PropTypes.string,
};

ProgressBar.defaultProps = {
  max: 100,
  infoAbove: null,
  infoBelow: null,
  className: null,
};

export default ProgressBar;


